  mov.u32 %r1, 0;
  st.local.u32 [%rd4+508], %r1;
  add.s64 %rd1, %rd3, 508;
  mov.u64 %rd5, 4;
  { // callseq 9 ... _bpf_helper_ext_0001 ... ld.param.b64 %rd9, [retval0+0]; } // callseq 9
  setp.eq.s64 %p1, %rd9, 0;
  @%p1 bra $L__BB0_2;
  st.u32 [%rd9], %rd14;
  st.u32 [%rd9+4], %rd16;
  st.u32 [%rd9+8], %rd17;
  st.u32 [%rd9+12], %rd18;
$L__BB0_2:
  ret;
plan_by_value accepts it: 16 bytes is not more than BYVALUE_MAX_BYTES (line 804). The function header (lines 1491-1498, inserted at 1538) then becomes
  .visible .func (.param .b64 __probe_func__kern_bpftime_tv_r0, .param .b64 __probe_func__kern_bpftime_tv_r1) __probe_func__kern(...)
and the kernel call (line 1386) becomes
